  'ext_agent_step_token_title': 'Подготовьте токен доступа',
  'ext_agent_step_token_desc': 'Навыку setup также нужен токен доступа. Полный токен показывается только один раз, при создании. Сохраните его сразу и передавайте только внешнему агенту, которому доверяете. Навык setup записывает токен в открытом виде в конфигурацию MCP и в .arcreel/settings.json. Если эти файлы лежат в репозитории кода, добавьте их в .gitignore, а те, что Git уже отслеживает, снимите с отслеживания, чтобы токен не попал в коммит.',
  'ext_agent_manage_tokens': 'Управление токенами доступа',
  'ext_agent_prompt_title': 'Пусть ИИ-агент подключит всё за вас',
  'ext_agent_prompt_desc': 'Отправьте этот промпт своему ИИ-агенту. Он прочитает отдельное руководство по установке и проведёт вас через навыки, MCP и проверку подключения.',
