  'agent_credentials': 'Провайдеры агента',
  'agent_providers_desc': 'Каждый провайдер агента — шлюз, совместимый с Anthropic. Одновременно активен только один провайдер; после переключения новые сессии используют новый провайдер, а уже запущенные остаются на предыдущем.',
  'arcreel_agent_section_desc': 'Агент [[brand]] — творческий агент в рабочем пространстве. Он вызывает модели через активного провайдера агента ниже.',
